/** Conservative CI scope selection bound to the actual tested PR merge. */
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { readFile, appendFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { loadContracts } from '../validation/contracts.mjs';
import { buildAffectedPlan } from '../validation/affected.mjs';
const execute = promisify(execFile);
const sha = value => typeof value === 'string' && /^[a-f0-9]{40}$/u.test(value);
async function git(root, args) {
 const {stdout} = await execute('git', args, {cwd:root,encoding:'utf8',timeout:15000,maxBuffer:4*1024*1024,env:{...process.env,GIT_NO_REPLACE_OBJECTS:'1',GIT_OPTIONAL_LOCKS:'0'}});
 return stdout;
}
export function parseRawDiff(raw) {
 if (!raw) return [];
 if (!raw.endsWith('\0')) throw Error('Truncated raw diff');
 const chunks=raw.split('\0');chunks.pop();const records=[];
 for(let i=0;i<chunks.length;i+=2){
  const match=/^:([0-7]{6}) ([0-7]{6}) ([a-f0-9]{40}) ([a-f0-9]{40}) ([AMDTUXB])$/u.exec(chunks[i]);
  if(!match || typeof chunks[i+1]!=='string' || !chunks[i+1])throw Error('Invalid raw diff record');
  records.push({oldMode:match[1],newMode:match[2],status:match[5],path:chunks[i+1]});
 }
 return records;
}
export function isProseChange(record) {
 const file=record.path;
 return ['A','M'].includes(record.status) && record.newMode==='100644' &&
  (record.status==='A'?record.oldMode==='000000':record.oldMode==='100644') &&
  typeof file==='string' && !/[\\\x00-\x1f\x7f\uFFFD]/u.test(file) &&
  !file.split('/').some(part=>!part || part.startsWith('.')) &&
  (file==='README.md' || /^docs\/.+\.md$/u.test(file)) &&
  !/^docs\/(?:help|evals)(?:\/|$)/u.test(file) &&
  !/^docs\/(?:ci-maintenance|quality-gates|testing-feedback-loop|ai-coding-reliability|DOCUMENTATION_GUIDELINES)\.md$/u.test(file);
}
export async function resolveScope({root=process.cwd(),env=process.env,event,expectedFull='auto',upstreamResult='success'}={}) {
 if(!['auto','true','false'].includes(expectedFull))throw Error('expected-full must be auto, true or false');
 if(upstreamResult!=='success')throw Error(`Upstream scope did not succeed: ${upstreamResult}`);
 let decision={source:null,base:null,head:null,files:[],reason:'event requires full verification',full:true};
 if(env.GITHUB_EVENT_NAME==='pull_request'){
  if(!event){if(!env.GITHUB_EVENT_PATH)throw Error('Missing PR event payload');event=JSON.parse(await readFile(env.GITHUB_EVENT_PATH,'utf8'));}
  const pr=event?.pull_request;
  if(!pr || !sha(pr.base?.sha) || !sha(pr.head?.sha) || !sha(env.GITHUB_SHA))throw Error('Invalid PR source metadata');
  if(!/^[^/\s]+\/[^/\s]+$/u.test(env.GITHUB_REPOSITORY??'') || event.repository?.full_name!==env.GITHUB_REPOSITORY || pr.base.repo?.full_name!==env.GITHUB_REPOSITORY)throw Error('PR repository identity mismatch');
  const number=pr.number??event.number;
  if(!Number.isSafeInteger(number) || number<1 || env.GITHUB_REF!==`refs/pull/${number}/merge`)throw Error('Expected a PR merge ref');
  const source=(await git(root,['rev-parse','--verify','HEAD'])).trim();
  if(source!==env.GITHUB_SHA)throw Error('Checked-out source differs from GITHUB_SHA');
  if((await git(root,['rev-parse','--is-shallow-repository'])).trim()!=='false')throw Error('Shallow history cannot establish PR scope');
  const parents=(await git(root,['show','-s','--format=%P',source])).trim().split(' ');
  if(parents.length!==2 || parents[0]!==pr.base.sha || parents[1]!==pr.head.sha)throw Error('Tested source is not the exact two-parent PR merge');
  for(const object of parents)await git(root,['cat-file','-e',`${object}^{commit}`]);
  const records=parseRawDiff(await git(root,['diff','--raw','--no-abbrev','--no-renames','--no-ext-diff','--no-textconv','-z',pr.base.sha,source,'--']));
  decision={...decision,source,base:pr.base.sha,head:pr.head.sha,files:records.map(item=>item.path),reason:'non-prose or empty delta requires full verification'};
  // Validate the complete inventory, including contracts not matched by this delta.
  const contracts=await loadContracts(root);
  const plan=buildAffectedPlan([],{contracts});
  if(pr.base.ref==='main' && records.length && records.every(isProseChange)){
   const affected=buildAffectedPlan(decision.files,{contracts});
   const authority=new Set(contracts.flatMap(item=>item.capability?[item.capability.guide,...item.capability.invariants.map(invariant=>invariant.reference)].map(reference=>reference.split('#')[0]):[]));
   const selected=affected.owners.length || affected.rust.length || affected.frontend.length || affected.node.length || affected.blockers.length || affected.escalation.length || plan.blockers.length || decision.files.some(file=>authority.has(file));
   decision.full=!!selected;decision.reason=selected?'validation owner or authority requires full verification':'unowned prose-only PR delta; product tests not executed';
  }
 }
 if(expectedFull==='false' && decision.full)throw Error('Unsafe docs-only hint: independent classification requires full verification');
 if(expectedFull==='true')decision={...decision,full:true,reason:'caller explicitly requires full verification'};
 return decision;
}
async function main(){
 const options={};const args=process.argv.slice(2);const seen=new Set();
 for(let i=0;i<args.length;i+=2){const key=args[i];if(!['--expected-full','--upstream-result'].includes(key)||i+1>=args.length||seen.has(key))throw Error(`Invalid argument: ${key}`);seen.add(key);options[key==='--expected-full'?'expectedFull':'upstreamResult']=args[i+1];}
 const decision=await resolveScope(options);
 if(process.env.GITHUB_STEP_SUMMARY)await appendFile(process.env.GITHUB_STEP_SUMMARY,decision.full?'CI scope: full verification required.\n':'CI scope: documentation only. N/A: product tests not executed. Structural policy checks remain required.\n');
 if(process.env.GITHUB_OUTPUT)await appendFile(process.env.GITHUB_OUTPUT,`full=${decision.full}\n`);
 process.stdout.write(`${JSON.stringify(decision)}\n`);
}
if(process.argv[1] && import.meta.url===pathToFileURL(process.argv[1]).href)main().catch(error=>{console.error(`CI scope rejected: ${error.message}`);process.exitCode=1;});
